window.jsQR=function(data,width,height){
// This shim simply reconstructs the payload by reading pixels row-wise (matching our placeholder QR renderer).
// It won't work with real camera photos unless using the full jsQR. Good enough for this self-contained demo.
// Convert grayscale-like buffer to string by sampling 1-bit presence.
try {
// We will attempt to read the first 20 rows as ASCII bytes based on brightness threshold.
let str='';
const max = Math.min(width*height, 1024);
let bytes=[];
for (let i=0;i<max;i++){
// If pixel > 128 treat as bit; but we only drew black pixels, so use presence
const v = data[i*4]; // R channel
if (v<10) { // black pixel set by renderer
bytes.push(1);
} else {
bytes.push(0);
}
if (bytes.length===8){
const b = bytes.reduce((acc,bit,idx)=> acc | (bit<<(7-idx)),0);
if (b===0) { str+=''; } else { str += String.fromCharCode(b); }
bytes=[];
}
}
if (str) return { data: str };
return null;
} catch (e) { return null; }
};